-- One multi-manifest typed fragment custody/execution engine; no financial history mutation.
BEGIN;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_lifecycle_operation_config(text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '28c5d03b9adb9dd4b4e83f3716a483ec63c50d9a98547988c983b064408205fd' THEN RAISE EXCEPTION 'tenant_financial_prior_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_lifecycle_operation_config(p_operation text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT $config${"supabase.tenant.export":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"export"},"supabase.tenant.manifests.export":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"export"},"supabase.tenant.erase":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"erase"},"supabase.tenant.manifests.erase":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"erase"},"supabase.tenant.restore":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"restore"},"supabase.tenant.manifests.restore":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"restore"},"supabase.tenant.exports.get":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"get"},"supabase.tenant.manifests.exports.get":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"get"},"supabase.tenant.exports.purge":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"purge"},"supabase.tenant.manifests.exports.purge":{"manifest":"application_scalar_links_v1","scope_sha256":"bde7aa35f375750e7fc7945e7012516b364c7ba8a4021c2319265dd8433c879e","action":"purge"},"supabase.tenant.protected_resources.inventory":{"manifest":"application_leaf_links_v1","scope_sha256":"f409867ca7bb8103d66fcfc4bdbc10fc5c8fc2a5849cd15b5ba3ba79d6d128a9","action":"inventory"},"supabase.tenant.content.export":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"content_export"},"supabase.tenant.content.exports.get":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"content_get"},"supabase.tenant.content.exports.purge":{"manifest":"customer_content_fragments_v1","scope_sha256":"f03c397e8c2ba3276d669cab643832a891899f6529274da2de1d6b52fd99c1ad","action":"purge"},"supabase.tenant.support.snapshot":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"export"},"supabase.tenant.support.erase":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"erase"},"supabase.tenant.support.restore":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"restore"},"supabase.tenant.support.snapshots.get":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"get"},"supabase.tenant.support.snapshots.purge":{"manifest":"support_case_recovery_v1","scope_sha256":"c691594174ef0f5b74c1c815568dab535a74a1b2f05f8a187bda3f41da1709b7","action":"purge"},"supabase.tenant.financial.export":{"manifest":"customer_financial_fragments_v1","scope_sha256":"bceaaef0ff9b597918fc55ac9658db0b928eaa85739a4ef8435fa7ca10a9085d","action":"content_export"},"supabase.tenant.financial.exports.get":{"manifest":"customer_financial_fragments_v1","scope_sha256":"bceaaef0ff9b597918fc55ac9658db0b928eaa85739a4ef8435fa7ca10a9085d","action":"content_get"},"supabase.tenant.financial.exports.purge":{"manifest":"customer_financial_fragments_v1","scope_sha256":"bceaaef0ff9b597918fc55ac9658db0b928eaa85739a4ef8435fa7ca10a9085d","action":"purge"}}$config$::jsonb->p_operation
$$;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_manifest_resolve(text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM 'b7677bc0937ebb12e2c76b26ca5a74998c27918f06fe47d2b3b488e3aac309a0' THEN RAISE EXCEPTION 'tenant_financial_prior_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_manifest_resolve(p_manifest text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF p_manifest='application_leaf_links_v1' THEN RETURN public.sandy_tenant_manifest_v1();
 ELSIF p_manifest='application_scalar_links_v1' THEN RETURN public.sandy_tenant_manifest_scalar_v1();
 ELSIF p_manifest='customer_content_fragments_v1' THEN RETURN public.sandy_tenant_content_manifest_v1();
 ELSIF p_manifest='support_case_recovery_v1' THEN RETURN public.sandy_tenant_support_manifest_v1();
 ELSIF p_manifest='customer_financial_fragments_v1' THEN RETURN public.sandy_tenant_financial_manifest_v1();
 ELSE RAISE EXCEPTION 'tenant_manifest_not_supported';END IF;
END $$;
ALTER TABLE public.sandy_tenant_content_snapshots ADD COLUMN manifest_id text NOT NULL DEFAULT 'customer_content_fragments_v1' CHECK(manifest_id IN('customer_content_fragments_v1','customer_financial_fragments_v1'));
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_content_metadata(public.sandy_tenant_content_snapshots)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM 'ba2b373228bc0ac0c7c120840637db9dcfa9ab69eeba53c639fafca8e79f04ce' THEN RAISE EXCEPTION 'tenant_financial_prior_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_content_metadata(p_snapshot public.sandy_tenant_content_snapshots) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
 SELECT jsonb_build_object('snapshot_id',(p_snapshot).id,'tenant_id',(p_snapshot).tenant_id,'manifest',(p_snapshot).manifest_id,'manifest_sha256',(p_snapshot).manifest_sha256,'schema_sha256',(p_snapshot).schema_sha256,'fragment_count',(p_snapshot).fragment_count,'row_counts',(p_snapshot).row_counts,'total_plaintext_bytes',(p_snapshot).total_plaintext_bytes,'artifact_index_sha256',(p_snapshot).artifact_index_sha256,'state',(p_snapshot).state,'created_at',(p_snapshot).created_at,'expires_at',(p_snapshot).expires_at,'complete_tenant_coverage',false,'external_provider_assets_included',false,'erasure_supported',false,'restore_supported',false)||CASE WHEN (p_snapshot).manifest_id='customer_financial_fragments_v1' THEN jsonb_build_object('financial_source','internal_commerce_records','provider_verified',false,'payment_executed',false) ELSE '{}'::jsonb END
$$;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_content_execute(uuid,uuid,text)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM 'f7187e245c10a921112028f43287aa70c5d2b7391ebd18836a8ceb53b8446cbb' THEN RAISE EXCEPTION 'tenant_financial_prior_source_changed';END IF;END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_content_execute(p_actor uuid,p_admission uuid,p_canonical text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp SET timezone='UTC' AS $$
DECLARE ctx jsonb;args jsonb;tenant uuid;op text;manifest jsonb;snapshot public.sandy_tenant_content_snapshots;fragment jsonb;fragment_row public.sandy_tenant_content_fragments;material text;vault_id uuid;index_data jsonb:='[]';index_sha text;counts jsonb:='{}';total_bytes bigint:=0;fragment_count integer:=0;snapshot_id uuid;result jsonb;previous jsonb;
BEGIN
 ctx:=public.sandy_tenant_lifecycle_context(p_actor,p_admission,p_canonical);args:=ctx->'arguments';tenant:=(ctx->>'tenant_id')::uuid;op:=ctx->>'operation';manifest:=public.sandy_tenant_manifest_resolve(ctx->>'manifest');
 IF op NOT IN('supabase.tenant.content.export','supabase.tenant.content.exports.get','supabase.tenant.content.exports.purge','supabase.tenant.financial.export','supabase.tenant.financial.exports.get','supabase.tenant.financial.exports.purge') OR ctx->>'manifest' IS DISTINCT FROM manifest->>'id' THEN RAISE EXCEPTION 'tenant_content_operation_not_supported';END IF;
 SELECT receipt.result INTO previous FROM public.sandy_tenant_content_receipts receipt WHERE receipt.admission_id=p_admission;
 IF FOUND THEN RETURN jsonb_build_object('ok',true,'result',previous,'reused',true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('tenant_manifest_lifecycle:'||tenant::text,0));
 IF op IN('supabase.tenant.content.export','supabase.tenant.financial.export') THEN
  snapshot_id:=gen_random_uuid();
  -- The STABLE capture SELECT uses one database statement snapshot for every
  -- source row/table while this outer function encrypts each bounded fragment.
  FOR fragment IN SELECT * FROM public.sandy_tenant_fragment_capture_v1(tenant,manifest->>'id') LOOP
   IF (fragment->>'sequence')::integer<>fragment_count OR fragment->>'tenant_id' IS DISTINCT FROM tenant::text OR fragment->>'manifest_sha256' IS DISTINCT FROM manifest->>'manifest_sha256' THEN RAISE EXCEPTION 'tenant_content_fragment_scope_failed';END IF;
   fragment:=fragment||jsonb_build_object('snapshot_id',snapshot_id,'schema_sha256',manifest->>'schema_sha256','complete_tenant_coverage',false,'external_provider_assets_included',false);
   material:=fragment::text;
   IF octet_length(material)>1048576 THEN RAISE EXCEPTION 'tenant_content_fragment_artifact_bound_exceeded';END IF;
   total_bytes:=total_bytes+octet_length(fragment->>'json_fragment');
   IF total_bytes>134217728 OR fragment_count>=2048 THEN RAISE EXCEPTION 'tenant_content_snapshot_bound_exceeded';END IF;
   SELECT vault.create_secret(material,'sandy_tenant_content_v1_'||snapshot_id::text||'_'||fragment_count::text,'Private typed customer-content fragment') INTO vault_id;
   IF NOT EXISTS(SELECT 1 FROM vault.decrypted_secrets WHERE id=vault_id AND decrypted_secret=material) THEN RAISE EXCEPTION 'tenant_content_fragment_encryption_readback_failed';END IF;
   index_data:=index_data||jsonb_build_array(jsonb_build_object('sequence',fragment_count,'table',fragment->>'table','artifact_sha256',encode(extensions.digest(material,'sha256'),'hex'),'artifact_bytes',octet_length(material),'vault_secret_id',vault_id));
   IF (fragment->>'table_complete')::boolean THEN counts:=counts||jsonb_build_object(fragment->>'table',(fragment->>'table_row_count')::integer);END IF;
   fragment_count:=fragment_count+1;
  END LOOP;
  IF fragment_count=0 OR (SELECT count(*) FROM jsonb_object_keys(counts))<>jsonb_array_length(manifest->'tables') THEN RAISE EXCEPTION 'tenant_content_capture_incomplete';END IF;
  -- Public index digest omits custody references and binds only safe sequence,
  -- table, byte count and exact canonical-artifact SHA-256 metadata.
  SELECT encode(extensions.digest(jsonb_agg(e.value-'vault_secret_id' ORDER BY (e.value->>'sequence')::integer)::text,'sha256'),'hex') INTO index_sha FROM jsonb_array_elements(index_data)e(value);
  INSERT INTO public.sandy_tenant_content_snapshots(id,tenant_id,manifest_id,manifest_sha256,schema_sha256,fragment_count,row_counts,total_plaintext_bytes,artifact_index_sha256,source_admission_id,expires_at) VALUES(snapshot_id,tenant,manifest->>'id',manifest->>'manifest_sha256',manifest->>'schema_sha256',fragment_count,counts,total_bytes,index_sha,p_admission,clock_timestamp()+interval '24 hours') RETURNING * INTO snapshot;
  INSERT INTO public.sandy_tenant_content_fragments(snapshot_id,sequence,artifact_sha256,vault_secret_id,table_name,artifact_bytes) SELECT snapshot_id,(e->>'sequence')::integer,e->>'artifact_sha256',(e->>'vault_secret_id')::uuid,e->>'table',(e->>'artifact_bytes')::integer FROM jsonb_array_elements(index_data)e;
 ELSE
  SELECT * INTO snapshot FROM public.sandy_tenant_content_snapshots WHERE id=(args->>'snapshot_id')::uuid AND tenant_id=tenant FOR UPDATE;
  IF snapshot.id IS NULL THEN RAISE EXCEPTION 'tenant_content_snapshot_not_found';END IF;
  IF snapshot.manifest_id IS DISTINCT FROM manifest->>'id' OR snapshot.manifest_sha256 IS DISTINCT FROM manifest->>'manifest_sha256' OR snapshot.schema_sha256 IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_content_snapshot_manifest_unsupported';END IF;
  IF op IN('supabase.tenant.content.exports.purge','supabase.tenant.financial.exports.purge') THEN
   IF args->>'confirm_artifact_purge' IS DISTINCT FROM 'true' OR snapshot.state='purged' THEN RAISE EXCEPTION 'tenant_content_purge_refused';END IF;
   FOR fragment_row IN SELECT * FROM public.sandy_tenant_content_fragments WHERE sandy_tenant_content_fragments.snapshot_id=snapshot.id FOR UPDATE LOOP
    IF fragment_row.vault_secret_id IS NULL OR EXISTS(SELECT 1 FROM public.sandy_credential_versions WHERE vault_secret_id=fragment_row.vault_secret_id) THEN RAISE EXCEPTION 'tenant_content_purge_custody_refused';END IF;
    DELETE FROM vault.secrets WHERE id=fragment_row.vault_secret_id AND name='sandy_tenant_content_v1_'||snapshot.id::text||'_'||fragment_row.sequence::text;
    IF NOT FOUND OR EXISTS(SELECT 1 FROM vault.secrets WHERE id=fragment_row.vault_secret_id) THEN RAISE EXCEPTION 'tenant_content_purge_readback_failed';END IF;
   END LOOP;
   UPDATE public.sandy_tenant_content_fragments SET vault_secret_id=NULL WHERE sandy_tenant_content_fragments.snapshot_id=snapshot.id;
   UPDATE public.sandy_tenant_content_snapshots SET state='purged' WHERE id=snapshot.id RETURNING * INTO snapshot;
  END IF;
 END IF;
 result:=public.sandy_tenant_content_metadata(snapshot);
 INSERT INTO public.sandy_tenant_content_receipts(admission_id,snapshot_id,result) VALUES(p_admission,snapshot.id,result);
 INSERT INTO public.sandy_tenant_lifecycle_events(tenant_id,snapshot_id,actor_id,admission_id,operation,before_sha256,after_sha256) VALUES(tenant,snapshot.id,p_actor,p_admission,op,snapshot.artifact_index_sha256,snapshot.artifact_index_sha256);
 RETURN jsonb_build_object('ok',true,'result',result,'reused',false);
END $$;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_content_fragment_download(uuid,integer)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM '599d0be12bbab9aee485f332500e92422c98d1e4f1505fc10f9cada43dea75b1' THEN RAISE EXCEPTION 'tenant_financial_prior_source_changed';END IF;END $$;
CREATE FUNCTION public.sandy_tenant_fragment_download_scoped(p_snapshot uuid,p_sequence integer,p_operation text,p_manifest text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());snapshot public.sandy_tenant_content_snapshots;fragment public.sandy_tenant_content_fragments;material text;payload jsonb;manifest jsonb;
BEGIN
 IF (p_operation='supabase.tenant.content.exports.download' AND p_manifest='customer_content_fragments_v1') IS NOT TRUE AND (p_operation='supabase.tenant.financial.exports.download' AND p_manifest='customer_financial_fragments_v1') IS NOT TRUE THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 manifest:=public.sandy_tenant_manifest_resolve(p_manifest);
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',403);END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation=p_operation AND handler='sandy-operation-api' AND api_exposed AND verified AND error_contract->>'requires_real_user_session'='true' AND error_contract->>'api_key_delegable'='false' AND error_contract->>'contract_sha256'=CASE p_operation WHEN 'supabase.tenant.content.exports.download' THEN 'e0f1b2f108bc2da6f4edb951e7b30eee93992452620ccf1fa06b2774f47da50b' ELSE 'e23689e3a6200dfaffc82fd485a43fc8be2b0afd17b1906ab2ce3c67ecab52da' END) THEN RETURN jsonb_build_object('ok',false,'http_status',424);END IF;
 IF p_sequence IS NULL OR p_sequence<0 OR p_sequence>=2048 THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 SELECT * INTO snapshot FROM public.sandy_tenant_content_snapshots WHERE id=p_snapshot AND tenant_id=tenant AND manifest_id=p_manifest FOR SHARE;
 IF snapshot.id IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 IF snapshot.expires_at<=clock_timestamp() OR snapshot.state='purged' THEN RETURN jsonb_build_object('ok',false,'http_status',410);END IF;
 IF snapshot.manifest_sha256 IS DISTINCT FROM manifest->>'manifest_sha256' OR snapshot.schema_sha256 IS DISTINCT FROM manifest->>'schema_sha256' THEN RAISE EXCEPTION 'tenant_content_snapshot_manifest_unsupported';END IF;
 SELECT * INTO fragment FROM public.sandy_tenant_content_fragments WHERE snapshot_id=p_snapshot AND sequence=p_sequence FOR SHARE;
 IF fragment.snapshot_id IS NULL OR fragment.vault_secret_id IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=fragment.vault_secret_id AND name='sandy_tenant_content_v1_'||p_snapshot::text||'_'||p_sequence::text;
 IF material IS NULL OR octet_length(material)>1048576 OR encode(extensions.digest(material,'sha256'),'hex') IS DISTINCT FROM fragment.artifact_sha256 THEN RAISE EXCEPTION 'tenant_content_fragment_integrity_failed';END IF;
 payload:=material::jsonb;
 IF payload->>'tenant_id' IS DISTINCT FROM tenant::text OR payload->>'snapshot_id' IS DISTINCT FROM p_snapshot::text OR payload->>'sequence' IS DISTINCT FROM p_sequence::text THEN RAISE EXCEPTION 'tenant_content_fragment_scope_failed';END IF;
 INSERT INTO public.sandy_tenant_lifecycle_events(tenant_id,snapshot_id,actor_id,operation,before_sha256,after_sha256) VALUES(tenant,p_snapshot,auth.uid(),p_operation,fragment.artifact_sha256,fragment.artifact_sha256);
 RETURN jsonb_build_object('ok',true,'snapshot_id',p_snapshot,'sequence',p_sequence,'artifact_sha256',fragment.artifact_sha256,'artifact_json',material);
END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_content_fragment_download(p_snapshot uuid,p_sequence integer) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT public.sandy_tenant_fragment_download_scoped(p_snapshot,p_sequence,'supabase.tenant.content.exports.download','customer_content_fragments_v1') $$;
CREATE FUNCTION public.sandy_tenant_financial_fragment_download(p_snapshot uuid,p_sequence integer) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT public.sandy_tenant_fragment_download_scoped(p_snapshot,p_sequence,'supabase.tenant.financial.exports.download','customer_financial_fragments_v1') $$;
DO $$BEGIN IF encode(extensions.digest((SELECT prosrc FROM pg_proc WHERE oid='public.sandy_tenant_content_exports_available(integer,integer)'::regprocedure),'sha256'),'hex') IS DISTINCT FROM 'eb68d55d118b1302faf2c7cb4abaaa5d72086a83e09f8ba1ab90b1258a032e86' THEN RAISE EXCEPTION 'tenant_financial_prior_source_changed';END IF;END $$;
CREATE FUNCTION public.sandy_tenant_fragment_exports_available_scoped(p_offset integer,p_limit integer,p_operation text,p_manifest text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE tenant uuid:=public.sandy_supabase_portal_tenant(auth.uid());total bigint;items jsonb;
BEGIN
 IF (p_operation='supabase.tenant.content.exports.available' AND p_manifest='customer_content_fragments_v1') IS NOT TRUE AND (p_operation='supabase.tenant.financial.exports.available' AND p_manifest='customer_financial_fragments_v1') IS NOT TRUE THEN RETURN jsonb_build_object('ok',false,'http_status',404);END IF;
 IF tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'http_status',403);END IF;
 IF NOT EXISTS(SELECT 1 FROM public.sandy_operation_registry WHERE operation=p_operation AND handler='sandy-operation-api' AND api_exposed AND verified AND error_contract->>'requires_real_user_session'='true' AND error_contract->>'api_key_delegable'='false' AND error_contract->>'contract_sha256'=CASE p_operation WHEN 'supabase.tenant.content.exports.available' THEN '73737340566cdcd1f6b9373aee20355a506710022867fe51e3beb30aa2847826' ELSE 'abe5538f563d0002e2f0fedf248cc568633b7d596186e76d5c1bf74c86787fc7' END) THEN RETURN jsonb_build_object('ok',false,'http_status',424);END IF;
 IF p_offset IS NULL OR p_offset<0 OR p_offset>2147483000 OR p_limit IS NULL OR p_limit<1 OR p_limit>50 THEN RAISE EXCEPTION 'tenant_content_pagination_invalid';END IF;
 SELECT count(*) INTO total FROM public.sandy_tenant_content_snapshots WHERE tenant_id=tenant AND manifest_id=p_manifest;
 IF total>2147483647 THEN RAISE EXCEPTION 'tenant_content_pagination_bound_exceeded';END IF;
 SELECT coalesce(jsonb_agg(public.sandy_tenant_content_metadata(page.snapshot) ORDER BY (page.snapshot).created_at DESC,(page.snapshot).id DESC),'[]'::jsonb) INTO items FROM(SELECT s AS snapshot FROM public.sandy_tenant_content_snapshots s WHERE s.tenant_id=tenant AND s.manifest_id=p_manifest ORDER BY s.created_at DESC,s.id DESC LIMIT p_limit OFFSET p_offset)page;
 RETURN jsonb_build_object('ok',true,'offset',p_offset,'limit',p_limit,'total_count',total,'next_offset',CASE WHEN p_offset+jsonb_array_length(items)<total THEN p_offset+jsonb_array_length(items) ELSE NULL END,'items',items);
END $$;
CREATE OR REPLACE FUNCTION public.sandy_tenant_content_exports_available(p_offset integer,p_limit integer) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT public.sandy_tenant_fragment_exports_available_scoped(p_offset,p_limit,'supabase.tenant.content.exports.available','customer_content_fragments_v1') $$;
CREATE FUNCTION public.sandy_tenant_financial_exports_available(p_offset integer,p_limit integer) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$ SELECT public.sandy_tenant_fragment_exports_available_scoped(p_offset,p_limit,'supabase.tenant.financial.exports.available','customer_financial_fragments_v1') $$;
